<?php

namespace App\Services;

use Illuminate\Support\Facades\Http;
use Illuminate\Support\Facades\Log;

class FamilyDataService
{
    public function getFamilyData($aadharNumber)
    {
        // Google Apps Script Proxy URL
        $googleScriptUrl = 'https://script.google.com/macros/s/AKfycbxHc14nb1hntQ8C9IbqJ63fH-ryYtC2SESXg0mnexcxVnYzoDD79krczInowQBfCjPwNg/exec';
        
        // Latest working cookies from your browser
        $cookies = 'ASP.NET_SessionId=2fulc3u0xwiva2hvwv2hnvvf; __RequestVerificationToken=rV4wE2rL2JZPm6Vk9XpixYdYPj3utKzpPJ7q_PsjQ8K6b1eGZq62cUKHc4AOe2aDFA-GfWoi89cqTjVly3RsVdpDW-sWSd6RtUFEpMVL-Yw1; ';

        try {
            // Send request to Google Apps Script instead of directly to Govt server
            $response = Http::timeout(60)->post($googleScriptUrl, [
                'aadhar' => base64_encode($aadharNumber),
                'cookies' => $cookies,
            ]);

            if ($response->successful()) {
                return $response->body();
            }

            Log::error('FamilyData via Google Proxy Failed', [
                'status' => $response->status(),
                'body' => $response->body(),
            ]);

        } catch (\Exception $e) {
            Log::error('FamilyData Proxy Exception', ['message' => $e->getMessage()]);
        }

        return null;
    }
}
